import heapq
class Solution:
    def secondGreaterElement(self, nums):
        n = len(nums)
        ans = [-1] * n
        heap = []
        order = sorted(range(n), key=lambda i: -nums[i])
        for idx in order:
            tmp = []
            while heap and nums[heap[0]] < nums[idx]:
                top = heapq.heappop(heap)
                if ans[top] == -2:
                    ans[top] = nums[idx]
                else:
                    ans[top] = -2
                    tmp.append(top)
            for t in tmp:
                heapq.heappush(heap, t)
            heapq.heappush(heap, idx)
        return [x if x != -2 else -1 for x in ans]

