class Solution {
    public int[] secondGreaterElement(int[] nums) {
        int n = nums.length;
        int[] ans = new int[n];
        Arrays.fill(ans, Integer.MIN_VALUE);
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        Integer[] order = new Integer[n];
        for (int i = 0; i < n; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> nums[b] - nums[a]);
        for (int idx : order) {
            List<Integer> tmp = new ArrayList<>();
            while (!pq.isEmpty() && nums[pq.peek()] < nums[idx]) {
                int top = pq.poll();
                if (ans[top] == Integer.MIN_VALUE) { ans[top] = Integer.MIN_VALUE + 1; tmp.add(top); }
                else ans[top] = nums[idx];
            }
            for (int t : tmp) pq.offer(t);
            pq.offer(idx);
        }
        for (int i = 0; i < n; i++) if (ans[i] < 0) ans[i] = -1;
        return ans;
    }
}

