var secondGreaterElement = function(nums) {
    const n = nums.length;
    const ans = new Array(n).fill(-1);
    const state = new Array(n).fill(0); // how many greater elements found
    const heap = []; // min-heap of indices
    const push = (x) => { heap.push(x); let i = heap.length - 1;
        while (i > 0) { const p = (i - 1) >> 1; if (heap[p] <= heap[i]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]]; i = p; } };
    const pop = () => { const top = heap[0]; const last = heap.pop();
        if (heap.length) { heap[0] = last; let i = 0;
            while (true) { let l = 2*i+1, r = l+1, m = i;
                if (l < heap.length && heap[l] < heap[m]) m = l;
                if (r < heap.length && heap[r] < heap[m]) m = r;
                if (m === i) break; [heap[m], heap[i]] = [heap[i], heap[m]]; i = m; } }
        return top; };
    const order = [...Array(n).keys()].sort((a, b) => nums[b] - nums[a]);
    for (const idx of order) {
        const tmp = [];
        while (heap.length && nums[heap[0]] < nums[idx]) {
            const top = pop();
            state[top]++;
            if (state[top] === 2) ans[top] = nums[idx];
            else tmp.push(top);
        }
        for (const t of tmp) push(t);
        push(idx);
    }
    return ans;
};

