class Solution {
    public int[] secondGreaterElement(int[] nums) {
        int n = nums.length;
        int[] ans = new int[n];
        Arrays.fill(ans, -1);
        Deque<Integer> s1 = new ArrayDeque<>(), s2 = new ArrayDeque<>();
        for (int j = 0; j < n; j++) {
            while (!s2.isEmpty() && nums[s2.peekLast()] < nums[j]) {
                ans[s2.pollLast()] = nums[j];
            }
            List<Integer> tmp = new ArrayList<>();
            while (!s1.isEmpty() && nums[s1.peekLast()] < nums[j]) {
                tmp.add(s1.pollLast());
            }
            for (int k = tmp.size() - 1; k >= 0; k--) s2.addLast(tmp.get(k));
            s1.addLast(j);
        }
        return ans;
    }
}

